examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchTabs(
        selectedIndex = lineSel,
        onSelectedIndexChange = { lineSel = it },
        modifier = Modifier.semantics { contentDescription = {{groups.0.label}} },
        panel = { index -> MonarchText(text = listOf({{groups.0.tabs.0.content}}, {{groups.0.tabs.1.content}}, "")[index]) },
    ) {
        tab({{groups.0.tabs.0.label}})
        tab({{groups.0.tabs.1.label}})
        tab({{groups.0.tabs.2.label}}, enabled = !{{groups.0.tabs.2.disabled}})
    }
    MonarchTabs(
        selectedIndex = pillSel,
        onSelectedIndexChange = { pillSel = it },
        modifier = Modifier.semantics { contentDescription = {{groups.1.label}} },
        variant = MonarchTabsVariant.Pill,
        panel = { index -> MonarchText(text = listOf({{groups.1.tabs.0.content}}, {{groups.1.tabs.1.content}}, {{groups.1.tabs.2.content}})[index]) },
    ) {
        tab({{groups.1.tabs.0.label}})
        tab({{groups.1.tabs.1.label}})
        tab({{groups.1.tabs.2.label}})
    }
}

examples.setupTemplate:
val lineValues = listOf({{groups.0.tabs.0.value}}, {{groups.0.tabs.1.value}}, {{groups.0.tabs.2.value}})
val pillValues = listOf({{groups.1.tabs.0.value}}, {{groups.1.tabs.1.value}}, {{groups.1.tabs.2.value}})
var lineSel by remember { mutableIntStateOf(lineValues.indexOf({{groups.0.selected}})) }
var pillSel by remember { mutableIntStateOf(pillValues.indexOf({{groups.1.selected}})) }

examples.setup:
val lineValues = listOf("board", "list", "timeline")
val pillValues = listOf("day", "week", "month")
var lineSel by remember { mutableIntStateOf(lineValues.indexOf("board")) }
var pillSel by remember { mutableIntStateOf(pillValues.indexOf("week")) }

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchTabs(
        selectedIndex = lineSel,
        onSelectedIndexChange = { lineSel = it },
        modifier = Modifier.semantics { contentDescription = "Views" },
        panel = { index -> MonarchText(text = listOf("Board view", "List view", "")[index]) },
    ) {
        tab("Board")
        tab("List")
        tab("Timeline", enabled = !true)
    }
    MonarchTabs(
        selectedIndex = pillSel,
        onSelectedIndexChange = { pillSel = it },
        modifier = Modifier.semantics { contentDescription = "Range" },
        variant = MonarchTabsVariant.Pill,
        panel = { index -> MonarchText(text = listOf("Day", "Week", "Month")[index]) },
    ) {
        tab("Day")
        tab("Week")
        tab("Month")
    }
}
